const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};
const auth = headers['authorization'] || headers['Authorization'] || '';
const token = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
if (!token) return { json: { ok: false, status: 401, error: 'Missing session token' } };
const f = body.filters || {};
const limit = Math.min(Math.max(parseInt(f.limit, 10) || 50, 1), 200);
const status = (f.status && f.status !== 'all') ? String(f.status) : '';
return { json: { token, limit, status } };

const rows = $input.item.json;
const row = Array.isArray(rows) ? (rows[0] || null) : (rows && (rows.id || rows.user_id) ? rows : null);

// Product entitlement. validate_session_for_product decides it centrally;
// this line only surfaces the verdict. Without it a 403
// product_not_entitled would be flattened into a 401 by the row check
// below, and a customer who had not bought Sales Engine would be told
// their session was invalid.
if (rows && rows.ok === false) return { json: { ok: false, status: rows.status || 401, error: rows.error, product: rows.product || null } };

const inputs = $('Extract Inputs').item.json;
if (!row) return { json: { ok: false, status: 401, error: 'Invalid or expired session' } };
if (row.user_role !== 'client' && row.user_role !== 'team_member') return { json: { ok: false, status: 403, error: 'Client access required' } };
if (!row.client_id) return { json: { ok: false, status: 403, error: 'No client mapped to session' } };
let qs = 'client_id=eq.' + encodeURIComponent(row.client_id)
       + '&select=id,company,industry,city,lead_status,lead_score,phone,source,date_created'
       + '&order=date_created.desc&limit=' + inputs.limit;
if (inputs.status) qs += '&lead_status=eq.' + encodeURIComponent(inputs.status);
return { json: { ok: true, qs } };

// Return the page AND how big the whole set is.
//
// The list asks for the newest 100 and renders them. With 1094 leads in
// the account that looks like an account with 100 leads -- there was no
// total anywhere in the response for the page to say otherwise. A page
// that cannot say 'showing 100 of 1094' is indistinguishable from one
// that is showing everything.
//
// PostgREST reports the unpaged count in Content-Range as 'a-b/total'
// when asked with Prefer: count=exact, so the number costs one header
// rather than a second query.
const first = $('Query Leads').first().json;

// fullResponse wraps the payload as { body, headers, statusCode }. Handle
// the unwrapped shape too, so this survives the option being changed.
const isWrapped = first && typeof first === 'object' && ('body' in first) && ('headers' in first);
const body    = isWrapped ? first.body    : null;
const headers = isWrapped ? (first.headers || {}) : {};

let leads;
if (Array.isArray(body)) {
  leads = body;
} else if (body && typeof body === 'object') {
  leads = Object.keys(body).length ? [body] : [];
} else {
  const items = $('Query Leads').all().map(function (i) { return i.json; });
  leads = (items.length === 1 && Array.isArray(items[0])) ? items[0]
        : items.filter(function (o) {
            return o && typeof o === 'object' && Object.keys(o).length > 0;
          });
}

// 'items 0-99/1094' or '0-99/1094' -- take what follows the slash. A '*'
// means the server declined to count; report null rather than invent one.
let total = null;
const cr = headers['content-range'] || headers['Content-Range'] || '';
const m = String(cr).match(/\/(\d+)\s*$/);
if (m) total = parseInt(m[1], 10);

return { json: {
  ok: true,
  leads: leads,
  returned: leads.length,
  total: total            // null = unknown, never a guess
} };
